-- Student User Accounts (User IDs 5 to 90 for the remaining 86 students)
-- Password for all student accounts: Student@123

-- Map all generated student users to ROLE_STUDENT
SELECT id, 4 FROM users WHERE id BETWEEN 5 AND 90;

-- Seed All 87 Student Profile Records (ID 1 = Dilkhush Kumar, IDs 2..87 = Classmates)

-- Biometric Enrollments for all 87 students
SELECT id, id, biometric_id, roll_no, 'ENROLLED', 'FINGERPRINT' FROM students;

-- Enroll all 87 students into all 10 B.Tech 1st Semester subjects
SELECT s.id, sub.id, 1, 1, '2026–2030', 'ACTIVE'
FROM students s
CROSS JOIN subjects sub;
